#include <MPU6050.h>
MPU6050 mpu;
float angle = 0;
unsigned long last_us = 0;
void loop() {
    int16_t gx, gy, gz;
    mpu.getRotation(&gx, &gy, &gz);
    float dps = {{axis}} / 131.0f;
    unsigned long now = micros();
    float dt = (now - last_us) / 1e6f;
    last_us = now;
    angle += dps * dt;
    Serial.println(angle);
}
